template <class Key, class GetKeyFromValue, class KeyCompare, class Container>
void flat_tree<Key, GetKeyFromValue, KeyCompare, Container>::replace(
    container_type&& body) {


  true ? (void)0 : ::logging::VoidifyStream(!(is_sorted_and_unique(body, value_comp()))) & (*::logging::g_swallow_stream);
  body_ = std::move(body);
}




template <class Key, class GetKeyFromValue, class KeyCompare, class Container>
auto flat_tree<Key, GetKeyFromValue, KeyCompare, Container>::erase(
    iterator position) -> iterator {
  __builtin_expect(!!(!(position != body_.end())), 0) ? logging::CheckFailure() : true ? (void)0 : ::logging::VoidifyStream() & (*::logging::g_swallow_stream);
  return body_.erase(position);
}

