  mojo::PlatformHandle TakeFd() {
    mojo::PlatformHandle result;
    bool ret =
        mojo::internal::Deserialize<mojo::PlatformHandle>(
            &data_->fd, &result, message_);
    true ? (void)0 : ::logging::VoidifyStream(!(ret)) & (*::logging::g_swallow_stream);
    return result;
  }
